// WE Quota Alert formatter (Arabic, RTL, HTML for Telegram)
const body = $input.first().json.body;

const {
  label, landline, customer_name, offer_name,
  threshold_pct, usage_pct, used_gb, remain_gb, total_gb,
  expire_time_iso, snapshot_taken_at
} = body;

// Renewal countdown
const nowMs = Date.now();
const renewalMs = new Date(expire_time_iso).getTime();
const daysLeft = Math.max(0, Math.ceil((renewalMs - nowMs) / 86400000));

const renewalLocal = new Date(expire_time_iso).toLocaleString('ar-EG', {
  timeZone: 'Africa/Cairo',
  year: 'numeric', month: 'short', day: '2-digit'
});

// Severity emoji
let emoji = '🟡';
if (usage_pct >= 95) emoji = '🔴';
else if (usage_pct >= 90) emoji = '🟠';

// Progress bar (20 chars)
const filled = Math.round((usage_pct / 100) * 20);
const bar = '█'.repeat(filled) + '░'.repeat(20 - filled);

// HTML message (Telegram supports <b>, <i>, <code>, <pre>)
const text = `${emoji} <b>تنبيه استهلاك باقة WE</b>

` +
  `📡 <b>الخط:</b> <code>${landline}</code>` +
  (label && label !== landline ? ` (${label})` : '') + `\n` +
  `👤 <b>العميل:</b> ${customer_name || '—'}\n` +
  `📦 <b>الباقة:</b> ${offer_name || '—'}\n\n` +
  `<b>الاستهلاك تخطى عتبة ${threshold_pct}%</b>\n` +
  `<pre>${bar}</pre>\n` +
  `📊 <b>${usage_pct.toFixed(1)}%</b> مستهلك\n` +
  `✅ المتبقي: <b>${remain_gb.toFixed(1)} GB</b>\n` +
  `🔻 المستخدم: ${used_gb.toFixed(1)} GB\n` +
  `🧮 الإجمالي: ${total_gb.toFixed(1)} GB\n\n` +
  `🗓 <b>التجديد بعد ${daysLeft} يوم</b> (${renewalLocal})\n` +
  `⏱ آخر فحص: ${new Date(snapshot_taken_at).toLocaleString('ar-EG', { timeZone: 'Africa/Cairo' })}`;

return [{
  json: {
    chat_id: $env.TELEGRAM_CHAT_ID || '',
    text,
    threshold_pct,
    landline,
    usage_pct
  }
}];
